float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_randomSeed;
uniform float amzp_useField;
uniform float amzp_lowpassType;
uniform float amzp_inputLuma;
uniform float amzp_chromaLowpassIn;
uniform float amzp_compositeSharpen;
uniform float amzp_chromaGain;
uniform float amzp_subcarrier;
uniform float amzp_noiseEnabled;
uniform float amzp_noiseIntensity;
uniform float amzp_noiseFrequency;
uniform float amzp_noiseDetail;
uniform float amzp_snow;
uniform float amzp_snowAnisotropy;
uniform float amzp_scanlinePhaseShift;
uniform float amzp_scanlinePhaseOffset;
uniform float amzp_chromaDemod;
uniform float amzp_lumaSmear;
uniform float amzp_headEnabled;
uniform float amzp_headHeight;
uniform float amzp_headOffset;
uniform float amzp_headHShift;
uniform float amzp_midLineEnabled;
uniform float amzp_midLinePosition;
uniform float amzp_midLineJitter;
uniform float amzp_trackingHeight;
uniform float amzp_trackingWaveIntensity;
uniform float amzp_trackingSnow;
uniform float amzp_trackingNoise;
uniform float amzp_intensity;
    float h11(float p){
        p = fract(p * 0.1031);
        p *= p + 33.33;
        p *= p + p;
        return fract(p);
    }
    float h21(float2 p){
        float3 p3 = fract(float3(p.xyx) * 0.1031);
        p3 += dot(p3, p3.yzx + 33.33);
        return fract((p3.x + p3.y) * p3.z);
    }
    float3 rgb2yiq(float3 c){
        float y = dot(c, float3(0.299, 0.587, 0.114));
        float i = dot(c, float3(0.595716, -0.274453, -0.321263));
        float q = dot(c, float3(0.211456, -0.522591, 0.311135));
        return float3(y, i, q);
    }
    float3 yiq2rgb(float3 c){
        float r = c.x + 0.9563 * c.y + 0.6210 * c.z;
        float g = c.x - 0.2721 * c.y - 0.6474 * c.z;
        float b = c.x - 1.1070 * c.y + 1.7046 * c.z;
        return float3(r, g, b);
    }
    float3 sampleYIQ(float2 uv){
        return rgb2yiq(amzTexture(0, clamp(uv, 0.001, 0.999)).rgb);
    }
    void amzRender(){
        float2 res = screen.zw;
        float2 uv = amzScreenNorm();
        float line = floor(uv.y * res.y);
        float seed = amzp_randomSeed * 0.137 + 1.0;
        float t = time;
        float invW = 1.0 / res.x;
        float invH = 1.0 / res.y;
        float linesFromBottom = res.y - line;
        float xshift = 0.0;
        if((amzp_headEnabled>0.5)){
            float hsTop = amzp_headOffset;
            float hsBottom = amzp_headOffset + amzp_headHeight;
            if(linesFromBottom > hsTop && linesFromBottom <= hsBottom){
                float f = (linesFromBottom - hsTop) / max(amzp_headHeight, 1.0);
                float sh = (amzp_headHShift * invW) * (1.0 - f);
                if((amzp_midLineEnabled>0.5)){
                    float jit = (h21(float2(line, seed)) - 0.5) * amzp_midLineJitter;
                    float amzLocal_pos = clamp(amzp_midLinePosition + jit, 0.0, 1.0);
                    if(uv.x > amzLocal_pos) xshift += sh;
                } else {
                    xshift += sh;
                }
            }
        }
        float tnActive = 0.0;
        if(linesFromBottom <= amzp_trackingHeight && amzp_trackingHeight > 0.5){
            float f = 1.0 - linesFromBottom / max(amzp_trackingHeight, 1.0);
            tnActive = f;
            float wav = sin(uv.y * res.y * 0.6 + t * 9.0) * (amzp_trackingWaveIntensity * invW) * f;
            wav += (h21(float2(line, seed + 7.0)) - 0.5) * (amzp_trackingWaveIntensity * invW) * f;
            xshift += wav;
        }
        float2 suv = float2(uv.x + xshift, uv.y);
        float xpix = (uv.x + xshift) * res.x;
        float sub = amzp_subcarrier;
        float phaseDeg = 0.0;
        if(int(amzp_scanlinePhaseShift) == 1) phaseDeg = 90.0;
        else if(int(amzp_scanlinePhaseShift) == 2) phaseDeg = 180.0;
        else if(int(amzp_scanlinePhaseShift) == 3) phaseDeg = 270.0;
        float demErr = radians(phaseDeg) * mod(line + amzp_scanlinePhaseOffset, 4.0);
        demErr += (h21(float2(line, seed + 3.0)) - 0.5) * 0.7;
        demErr += t * 0.6;
        float sY = 0.0, sI = 0.0, sQ = 0.0, wsum = 0.0;
        for(int k = -6; k <= 6; k++){
            float fk = float(k);
            float3 s = sampleYIQ(suv + float2(fk * invW, 0.0));
            float xp = xpix + fk;
            float encP = sub * xp;
            float demP = sub * xp + demErr;
            float comp = s.x + s.y * cos(encP) + s.z * sin(encP);
            float w = exp(-fk * fk * 0.16);
            sY += comp * w;
            sI += comp * cos(demP) * w;
            sQ += comp * sin(demP) * w;
            wsum += w;
        }
        float Yo = sY / wsum;
        float Io = 2.0 * sI / wsum * amzp_chromaGain;
        float Qo = 2.0 * sQ / wsum * amzp_chromaGain;
        float3 yiq = float3(Yo, Io, Qo);
        if(int(amzp_chromaDemod) == 0){
            float3 a = sampleYIQ(suv + float2( invW, 0.0));
            float3 b = sampleYIQ(suv + float2(-invW, 0.0));
            yiq.y = (yiq.y + a.y * amzp_chromaGain + b.y * amzp_chromaGain) / 3.0;
            yiq.z = (yiq.z + a.z * amzp_chromaGain + b.z * amzp_chromaGain) / 3.0;
        } else if(int(amzp_chromaDemod) == 2 || int(amzp_chromaDemod) == 3){
            float3 up = sampleYIQ(suv + float2(0.0, invH));
            float3 up2 = (int(amzp_chromaDemod) == 3) ? sampleYIQ(suv + float2(0.0, 2.0 * invH)) : up;
            yiq.y = mix(yiq.y, (up.y + up2.y) * 0.5 * amzp_chromaGain, 0.5);
            yiq.z = mix(yiq.z, (up.z + up2.z) * 0.5 * amzp_chromaGain, 0.5);
        }
        float chromaPx = 0.0;
        if(int(amzp_chromaLowpassIn) == 1) chromaPx = 1.5;
        else if(int(amzp_chromaLowpassIn) == 2) chromaPx = 2.5;
        if(int(amzp_lowpassType) == 1) chromaPx *= 0.7;
        else if(int(amzp_lowpassType) == 2) chromaPx = 0.0;
        if(chromaPx > 0.01){
            float si = 0.0, sq = 0.0, sw = 0.0;
            for(int k = -3; k <= 3; k++){
                float fk = float(k);
                float xp = xpix + fk * chromaPx;
                float3 s = sampleYIQ(suv + float2(fk * chromaPx * invW, 0.0));
                float encP = sub * xp;
                float demP = sub * xp + demErr;
                float comp = s.x + s.y * cos(encP) + s.z * sin(encP);
                float w = exp(-fk * fk * 0.35);
                si += comp * cos(demP) * w;
                sq += comp * sin(demP) * w;
                sw += w;
            }
            yiq.y = 2.0 * si / sw * amzp_chromaGain;
            yiq.z = 2.0 * sq / sw * amzp_chromaGain;
        }
        if(int(amzp_inputLuma) == 2){
            float yl = 0.0, w = 0.0;
            for(int k = -2; k <= 2; k++){
                float fk = float(k);
                yl += sampleYIQ(suv + float2(fk * invW, 0.0)).x; w += 1.0;
            }
            yiq.x = yl / w;
        } else if(int(amzp_inputLuma) == 1){
            float yb = 0.0, w = 0.0;
            for(int k = -2; k <= 2; k++){
                float fk = float(k);
                yb += sampleYIQ(suv + float2(fk * invW, 0.0)).x; w += 1.0;
            }
            yb /= w;
            yiq.x += (yiq.x - yb) * 0.6;
        }
        if((amzp_noiseEnabled>0.5)){
            float nfreq = mix(2.0, 40.0, amzp_noiseFrequency);
            float n = (h21(float2(line * 0.5 + floor(t * 60.0), seed)) - 0.5);
            int oct = int(amzp_noiseDetail + 0.5);
            float amp = 0.5;
            for(int o = 0; o < 5; o++){
                if(o >= oct) break;
                float fo = float(o) + 1.0;
                n += (h21(float2(uv.x * res.x * (nfreq * 0.02) * fo + line, seed + fo)) - 0.5) * amp;
                amp *= 0.6;
            }
            yiq.x += n * amzp_noiseIntensity * 0.6;
        }
        if(amzp_lumaSmear > 0.001){
            float sm = amzp_lumaSmear * 10.0 * invW;
            float yl = sampleYIQ(suv - float2(sm, 0.0)).x;
            yiq.x = mix(yiq.x, max(yiq.x, yl * 0.95), amzp_lumaSmear);
        }
        if(abs(amzp_compositeSharpen) > 0.001){
            float yb = 0.0, w = 0.0;
            for(int k = -2; k <= 2; k++){
                float fk = float(k);
                yb += sampleYIQ(suv + float2(fk * invW, 0.0)).x; w += 1.0;
            }
            yb /= w;
            yiq.x += (yiq.x - yb) * amzp_compositeSharpen;
        }
        if(int(amzp_useField) != 3){
            float parity = mod(line + floor(t * 50.0), 2.0);
            if(int(amzp_useField) == 1) parity = mod(line + 1.0 + floor(t * 50.0), 2.0);
            if(int(amzp_useField) != 2){
                yiq.x *= (1.0 - 0.10 * parity);
            }
        }
        if(amzp_snow > 0.001){
            float ax = floor(uv.x * res.x / mix(1.0, 6.0, amzp_snowAnisotropy));
            float sp = h21(float2(ax + floor(t * 120.0) * 1.3, line * 1.7 + seed));
            float thresh = 1.0 - clamp(amzp_snow * 0.01, 0.0, 1.0);
            if(sp > thresh){
                yiq = float3(0.9, 0.0, 0.0);
            }
        }
        if(tnActive > 0.001){
            float st = h21(float2(uv.x * res.x + floor(t * 120.0) * 1.9, line + seed + 11.0));
            yiq.x = mix(yiq.x, st, amzp_trackingSnow * tnActive);
            yiq.x += (st - 0.5) * amzp_trackingNoise * tnActive;
        }
        float3 outc = clamp(yiq2rgb(yiq), 0.0, 1.0);
        float3 orig = amzTexture(0, clamp(uv, 0.001, 0.999)).rgb;
        amzOutput = float4(mix(orig, outc, amzp_intensity), 1.0);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

